//! 🔬️ Joint presentation laws: capture, atomic update, foreign-original refusal, seed admission and slot publication.

use super::*;
use semio_framework_tool_run::*;
use serde_json::Value;
use crate::effect_harness;
use super::{update::ToolRunPresentationUpdate,slot::ToolRunPresentationSlot};
use semio_framework_tool_run_entities::ToolRunEntityEditGrant;
use semio_framework_value::{retained_clone::{RetainedAllocationEffect,RetainedCloneGrant},retirement::{RetireOwned,controlled::ControlledRetirement},RetainedWorkOutcome,RetainedWorkPoll};

const CPU:u64=1<<20;
fn setup()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:1<<10}}
fn measured<R>(work:impl FnOnce()->R)->(R,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(work);(value,(heap.requested_bytes,heap.released_bytes))}
fn run<R>(grant:RetainedCloneGrant,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->R)->R{let mut bank=effect_harness::bank();let(poll,_)=bank.run(grant,CPU,|effect|{let boundary=effect.performed_boundary();let value=operation(effect);let work=effect.performed_since(boundary).unwrap();RetainedWorkPoll::Complete(RetainedWorkOutcome::<R,semio_framework_value::ValueError>{result:Ok(value),work})});match poll{RetainedWorkPoll::Complete(turn)=>turn.result.unwrap(),RetainedWorkPoll::Pending{..}=>panic!("presentation fixture primitive pending")}}
fn observed<R>(grant:RetainedCloneGrant,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->R)->(R,(usize,usize)){run(grant,|effect|measured(||operation(effect)))}
fn settled<T,E>(poll:RetainedWorkPoll<T,E>)->RetainedWorkOutcome<T,E>{match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("original presentation fixture turn stayed pending")}}
fn drain<T:RetireOwned>(value:T)->(usize,usize){effect_harness::retire(&mut effect_harness::bank(),value)}
fn turn(job:&mut ToolRunPresentationUpdate,bank:&mut semio_framework_value_testing_effect_bank::EffectBank,grant:ToolRunEntityEditGrant)->effect_harness::Observed{effect_harness::paid(bank,grant.retirement,|e,r,recover|if recover{job.recover_advance_into(usize::MAX,grant,e,r)}else{job.advance_into(usize::MAX,grant,e,r)})}
fn slot_turn(slot:&mut ToolRunPresentationSlot,bank:&mut semio_framework_value_testing_effect_bank::EffectBank,grant:ToolRunEntityEditGrant)->effect_harness::Observed{effect_harness::paid(bank,grant.retirement,|e,r,recover|if recover{slot.recover_advance_into(usize::MAX,grant,e,r)}else{slot.advance_into(usize::MAX,grant,e,r)})}

const TICKS: &str = include_str!("../../../../🧪️tests/🧫️fixtures/🎞️ticks.json");

fn fixture(text: &str) -> Value {
    serde_json::from_str(text).expect("fixture parses")
}

#[test]
fn original_tool_run_progress_metadata_presentation_captures_keep_joint_original_body(){
 use semio_framework_value::{retained_clone::{RetainedCloneGrant,ordered_map::RetainedOrderedMap},retirement::{RetireOwned,controlled::ControlledRetirement}};
 use semio_framework_value_shared_issuance::{SealedShared,SharedIssuer};
 use super::{ToolRunPresentation,ToolRunPresentationBody};
 use semio_framework_tool_run_entities::provenance::ToolRunEntityProvenance;
 let law:Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let corpus=fixture(TICKS);
 for bytes in law["payloadCases"].as_array().unwrap(){for order in law["orders"].as_array().unwrap(){
  let(mut body,heap)=measured(||{let marks:RetainedOrderedMap<u128,()>=[((1u128<<64)|7,()),((3u128<<64)|9,())].into_iter().collect();let entities=[(7u64,()),(9,())].into_iter().collect();let(provenance,_)=run(setup(),|effect|ToolRunEntityProvenance::admit(marks,entities,0,effect)).unwrap_or_else(|_|panic!("cold fixture original provenance"));let payload=fixture_payload(hex(bytes),identity(&corpus["ticks"][0]["tick"]["identity"]));let tool_id=run(setup(),|effect|semio_framework_tool_run_entities::admit_sealed(String::from("draw.command"),effect)).map_err(|(error,_)|error).unwrap().0;ToolRunPresentationBody{tool_id,progress:progress(&corpus["ticks"][0]["tick"]["progress"]),provenance,payload:Some(payload)}});let original=heap.0-heap.1;let tool_pointer=body.tool_id.as_ptr();let counter_pointer=body.progress.counters.as_ptr();let payload_pointer=body.payload.as_ref().unwrap().get().contiguous().unwrap().as_ptr();let provenance_pointer=body.provenance.identity();let quote=ToolRunPresentation::birth_demands().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:quote.copy_bytes,maximum_capacity_bytes:quote.capacity_bytes,maximum_depth:quote.depth,..Default::default()};
  for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observed(denied,|effect|ToolRunPresentation::admit(body,effect));assert_eq!(heap,(0,0));let(_,returned)=result.err().unwrap();body=returned;assert_eq!(body.tool_id.as_ptr(),tool_pointer);assert_eq!(body.progress.counters.as_ptr(),counter_pointer);assert_eq!(body.payload.as_ref().unwrap().get().contiguous().unwrap().as_ptr(),payload_pointer);}
  let(admitted,heap)=observed(grant,|effect|ToolRunPresentation::admit(body,effect));let(presentation,receipt)=admitted.map_err(|(error,_)|error).unwrap();assert!(receipt.fits(grant));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));let(mut born,mut released)=(heap.0,heap.1);let identity=presentation.identity();let mut source=Some(presentation);let mut captures=[None,None,None];let capture_grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:ToolRunPresentation::capture_copy_bytes(),maximum_depth:1,..Default::default()};
  for capture in &mut captures{for denied in [RetainedCloneGrant{maximum_items:0,..capture_grant},RetainedCloneGrant{maximum_copy_bytes:0,..capture_grant},RetainedCloneGrant{maximum_depth:0,..capture_grant}]{let(result,heap)=observed(denied,|effect|source.as_ref().unwrap().capture(effect));assert!(result.is_err());assert_eq!(heap,(0,0));}let((alias,receipt),heap)=observed(capture_grant,|effect|source.as_ref().unwrap().capture(effect).unwrap());assert!(receipt.fits(capture_grant));assert_eq!(heap,(0,0));assert_eq!(alias.identity(),identity);*capture=Some(alias);}
  let steps=if order.as_str().unwrap()=="sourceFirst"{[3,0,1,2]}else{[0,1,2,3]};for index in steps{for live in source.iter().chain(captures.iter().flatten()){assert_eq!(live.identity(),identity);assert_eq!(live.body().tool_id.as_ptr(),tool_pointer);assert_eq!(live.body().progress.counters.as_ptr(),counter_pointer);assert_eq!(live.body().payload.as_ref().unwrap().get().contiguous().unwrap().as_ptr(),payload_pointer);assert_eq!(live.body().provenance.identity(),provenance_pointer);}let value=if index==3{source.take().unwrap()}else{captures[index].take().unwrap()};let heap=drain(value);born+=heap.0;released+=heap.1;}
  assert_eq!(original+born,released);
 }}
}

#[test]
fn original_tool_run_progress_metadata_presentation_update_is_atomic_and_physically_owned(){
 use semio_framework_value::{retained_clone::{RetainedCloneGrant,ordered_map::{RetainedOrderedMap,BoundedOrdGrant}},retirement::{RetireOwned,controlled::ControlledRetirement}};
 use semio_framework_value_shared_issuance::{SealedShared,SharedIssuer};
 use super::{ToolRunPresentation,ToolRunPresentationBody,update::ToolRunPresentationUpdate};
 use semio_framework_tool_run_entities::{ToolRunEntityEditGrant,provenance::ToolRunEntityProvenance};
 let law:Value=serde_json::from_str(include_str!("../../🧬️update/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let corpus=fixture(TICKS);let ring_law:Value=serde_json::from_str(include_str!("../../../💍️steps/➕️insert/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for with_progress in [false,true]{for payload in law["payloadCases"].as_array().unwrap(){for stop in std::iter::once(None).chain(law["interruptAfter"].as_array().unwrap().iter().map(|x|Some(x.as_u64().unwrap()as usize))){for source_first in [false,true]{
  let((source,input),heap)=measured(||{let marks:RetainedOrderedMap<u128,()>=law["originalMarks"].as_array().unwrap().iter().map(|mark|(((mark["end"].as_u64().unwrap()as u128)<<64)|mark["entity"].as_str().unwrap().parse::<u64>().unwrap()as u128,())).collect();let entities=[(7u64,()),(9,())].into_iter().collect();let(provenance,_)=run(setup(),|effect|ToolRunEntityProvenance::admit(marks,entities,0,effect)).unwrap_or_else(|_|panic!("cold original provenance"));let tool_id=run(setup(),|effect|semio_framework_tool_run_entities::admit_sealed(String::from("draw.command"),effect)).map_err(|(error,_)|error).unwrap().0;let bytes=fixture_payload(vec![4u8,5],identity(&corpus["ticks"][0]["tick"]["identity"]));let progress=progress(&corpus["ticks"][0]["tick"]["progress"]);let identity=progress.identity;let sequence=progress.sequence+1;let quote=ToolRunPresentation::birth_demands().unwrap();let(source,_)=run(setup(),|effect|ToolRunPresentation::admit(ToolRunPresentationBody{tool_id,progress,provenance,payload:Some(bytes)},effect)).unwrap_or_else(|_|panic!("cold original presentation"));let input=ToolRunTick{payload_update:None,identity,sequence,progress:if with_progress{let mut update=self::progress(&corpus["ticks"][0]["tick"]["progress"]);update.stage=17;update.completed=99;update.total=Some(3);update.counters=vec![ToolRunCounter{counter:2,value:5}];Some(update)}else{None},steps:vec![step(&ring_law["cases"][0]["input"])],trace:Vec::new(),append_ops:Vec::new(),append_entities:law["append"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().parse().unwrap()).collect(),retract_to:Some(law["retractTo"].as_u64().unwrap()as u32),payload:(!payload.is_null()).then(||hex(payload))};(source,input)});let original=heap.0-heap.1;let original_pointer=source.identity();let original_counters=source.body().progress.counters.as_ptr();let original_payload=source.body().payload.as_ref().unwrap().get().contiguous().unwrap().as_ptr();let input_payload=input.payload.as_ref().map(|bytes|bytes.as_ptr());let input_counters=input.progress.as_ref().map(|progress|progress.counters.as_ptr());let sequence=input.sequence;let alias=run(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:ToolRunPresentation::capture_copy_bytes(),maximum_depth:1,..Default::default()},|effect|source.capture(effect)).unwrap().0;let d=ToolRunPresentationUpdate::birth_demands();let((mut job,p),heap)=measured(||ToolRunPresentationUpdate::admit(alias,input,law["end"].as_u64().unwrap()as u32,ToolRunState::Running,0.0,0,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_depth:d.depth,..Default::default()}).unwrap_or_else(|_|panic!("original presentation state birth was funded")));assert_eq!(heap,(p.retained_capacity_bytes,0));let(mut born,mut released,mut turns)=(heap.0,0,0);
  let mut bank=effect_harness::bank();while !job.complete()&&turns<stop.unwrap_or(100000){let quote=job.next_demands(usize::MAX).unwrap();let grant=ToolRunEntityEditGrant{retirement:RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:quote.copy_bytes,maximum_capacity_bytes:quote.capacity_bytes,maximum_release_bytes:quote.release_bytes,maximum_depth:quote.depth},comparison:BoundedOrdGrant{maximum_items:1,maximum_bytes:32},maximum_moved_items:17,maximum_moved_bytes:17*size_of::<(u128,())>(),maximum_capacity_bytes:job.edit_capacity_bound().unwrap()};for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant.retirement}),grant.retirement.maximum_copy_bytes.checked_sub(1).map(|v|RetainedCloneGrant{maximum_copy_bytes:v,..grant.retirement}),grant.retirement.maximum_capacity_bytes.checked_sub(1).map(|v|RetainedCloneGrant{maximum_capacity_bytes:v,..grant.retirement}),grant.retirement.maximum_release_bytes.checked_sub(1).map(|v|RetainedCloneGrant{maximum_release_bytes:v,..grant.retirement}),grant.retirement.maximum_depth.checked_sub(1).map(|v|RetainedCloneGrant{maximum_depth:v,..grant.retirement})].into_iter().flatten(){let o=turn(&mut job,&mut bank,ToolRunEntityEditGrant{retirement:denied,..grant});assert_eq!(o.progress,Default::default(),"turn={turns} quote={quote:?} denied={denied:?}");assert_eq!(o.heap,(0,0));assert_eq!(job.next_demands(usize::MAX).unwrap(),quote);}let o=turn(&mut job,&mut bank,grant);assert!(o.progress.fits(grant.retirement));born+=o.heap.0;released+=o.heap.1;assert_eq!(source.identity(),original_pointer);assert_eq!(source.body().progress.counters.as_ptr(),original_counters);turns+=1;}
  let output=if stop.is_none(){assert!(job.complete());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:size_of::<ToolRunPresentation>(),maximum_depth:1,..Default::default()};assert!(job.take_output(Default::default()).unwrap().is_none());let(output,receipt)=job.take_output(grant).unwrap().unwrap();assert!(receipt.fits(grant));assert_ne!(output.identity(),source.identity());assert_eq!(output.body().tool_id.as_ptr(),source.body().tool_id.as_ptr());assert_eq!(output.body().progress.sequence,sequence);if with_progress{assert_eq!(output.body().progress.stage,17);assert_eq!(output.body().progress.completed,3);assert_eq!(output.body().progress.counters.as_ptr(),input_counters.unwrap());}let entities:Vec<_>=output.body().provenance.entities().iter().map(|(key,_)|key.to_string()).collect();assert_eq!(entities,law["expectedEntities"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<Vec<_>>());assert_eq!(output.body().payload.as_ref().unwrap().get().contiguous().unwrap().as_ptr(),input_payload.unwrap_or(original_payload));Some(output)}else{job.cancel();assert!(job.take_output(Default::default()).unwrap().is_none());None};let heap=effect_harness::retire(&mut bank,job);born+=heap.0;released+=heap.1;let mut source=Some(source);let mut output=output;for first in [source_first,!source_first]{let value=if first{source.take()}else{output.take()};if let Some(value)=value{let heap=drain(value);born+=heap.0;released+=heap.1;}}assert_eq!(original+born,released);
 }}}}
}

#[test]
fn original_tool_run_progress_metadata_presentation_update_refuses_foreign_original_without_drop(){
 use semio_framework_value::{retained_clone::RetainedCloneGrant,retirement::{RetireOwned,controlled::ControlledRetirement}};
 use semio_framework_value_shared_issuance::{SealedShared,SharedIssuer};
 use super::{ToolRunPresentation,ToolRunPresentationBody,update::ToolRunPresentationUpdate};
 use semio_framework_tool_run_entities::{ToolRunEntityEditGrant,provenance::ToolRunEntityProvenance};
 let law:Value=serde_json::from_str(include_str!("../../🧬️update/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["foreignRun"],true);let corpus=fixture(TICKS);
 for source_first in [false,true]{let((source,input),heap)=measured(||{let(provenance,_)=run(setup(),|effect|ToolRunEntityProvenance::admit(Default::default(),Default::default(),0,effect)).unwrap_or_else(|_|panic!("cold original provenance"));let tool_id=run(setup(),|effect|semio_framework_tool_run_entities::admit_sealed(String::from("draw.command"),effect)).map_err(|(error,_)|error).unwrap().0;let progress=progress(&corpus["ticks"][0]["tick"]["progress"]);let mut identity=progress.identity;identity.id.run+=1;let quote=ToolRunPresentation::birth_demands().unwrap();let(source,_)=run(setup(),|effect|ToolRunPresentation::admit(ToolRunPresentationBody{tool_id,progress,provenance,payload:None},effect)).unwrap_or_else(|_|panic!("cold original presentation"));(source,ToolRunTick{payload_update:None,identity,sequence:1,progress:None,steps:Vec::new(),trace:Vec::new(),append_ops:vec![vec![3,4,5]],append_entities:vec![7],retract_to:None,payload:Some(vec![8,9])})});let original=heap.0-heap.1;let pointer=source.identity();let counters=source.body().progress.counters.as_ptr();let capture=run(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:ToolRunPresentation::capture_copy_bytes(),maximum_depth:1,..Default::default()},|effect|source.capture(effect)).unwrap().0;let d=ToolRunPresentationUpdate::birth_demands();let((mut job,p),birth)=measured(||ToolRunPresentationUpdate::admit(capture,input,1,ToolRunState::Running,0.0,0,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_depth:d.depth,..Default::default()}).unwrap_or_else(|_|panic!("original presentation birth was funded")));assert_eq!(birth,(p.retained_capacity_bytes,0));let(fault,heap)=observed(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:ToolRunPresentation::capture_copy_bytes(),maximum_depth:1,..Default::default()},|effect|{let mut slot=None;job.advance_into(usize::MAX,ToolRunEntityEditGrant{retirement:RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:ToolRunPresentation::capture_copy_bytes(),maximum_depth:1,..Default::default()},..Default::default()},effect,semio_framework_value::retained_clone::OriginalEffectReply::borrow(&mut slot).unwrap()).map(drop)});assert_eq!(fault.err().unwrap().kind,semio_framework_value::ValueRefusalKind::InvalidValue);assert_eq!(heap,(0,0));assert_eq!(source.identity(),pointer);assert_eq!(source.body().progress.counters.as_ptr(),counters);assert!(!job.complete());assert!(job.take_output(Default::default()).unwrap().is_none());job.cancel();let(mut born,mut released)=(birth.0,0);let mut source=Some(source);let mut job=Some(job);for first in [source_first,!source_first]{let heap=if first{drain(source.take().unwrap())}else{drain(job.take().unwrap())};born+=heap.0;released+=heap.1;}assert_eq!(original+born,released);}
}

#[test]
fn original_tool_run_progress_metadata_presentation_seed_is_admitted_without_identifier_copy(){
 use super::seed::ToolRunPresentationSeed;
 use semio_framework_value::{retained_clone::RetainedCloneGrant,retirement::{RetireOwned,controlled::ControlledRetirement}};
 let law:Value=serde_json::from_str(include_str!("../../🌱️seed/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in law["toolIds"].as_array().unwrap(){for stop in std::iter::once(None).chain(law["interruptAfter"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize))){let(id,heap)=measured(||row.as_str().unwrap().to_owned());let original=heap.0-heap.1;let pointer=id.as_ptr();let identity=identity(&fixture(TICKS)["ticks"][0]["tick"]["identity"]);let(mut seed,heap)=measured(||ToolRunPresentationSeed::new(id,identity,ToolRunState::Starting));assert_eq!(heap,(0,0));let(mut born,mut released,mut turns)=(0,0,0);while !seed.complete()&&turns<stop.unwrap_or(100){let quote=seed.next_demands().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:quote.copy_bytes,maximum_capacity_bytes:quote.capacity_bytes,maximum_release_bytes:quote.release_bytes,maximum_depth:quote.depth};for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(receipt,heap)=observed(denied,|effect|seed.advance(effect).unwrap());assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());assert_eq!(seed.original_identifier().map(str::as_ptr),Some(pointer));assert_eq!(seed.next_demands().unwrap(),quote);}if quote.copy_bytes>0{let(receipt,heap)=observed(RetainedCloneGrant{maximum_copy_bytes:quote.copy_bytes-1,..grant},|effect|seed.advance(effect).unwrap());assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));}if quote.capacity_bytes>0{let(receipt,heap)=observed(RetainedCloneGrant{maximum_capacity_bytes:quote.capacity_bytes-1,..grant},|effect|seed.advance(effect).unwrap());assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));}let(receipt,heap)=observed(grant,|effect|seed.advance(effect).unwrap());assert_ne!(receipt,Default::default(),"seed stalled under its exact quote {quote:?}");assert!(receipt.fits(grant));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;released+=heap.1;assert_eq!(seed.original_identifier().map(str::as_ptr),Some(pointer));turns+=1;}
  if stop.is_none(){let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:std::mem::size_of::<super::ToolRunPresentation>(),maximum_depth:1,..Default::default()};assert!(seed.take_output(RetainedCloneGrant{maximum_items:0,..grant}).unwrap().is_none());let((output,receipt),heap)=measured(||seed.take_output(grant).unwrap().unwrap());assert!(receipt.fits(grant));assert_eq!(heap,(0,0));let body=output.body();assert_eq!(body.tool_id.get().as_ptr(),pointer);assert_eq!(body.tool_id.get(),row.as_str().unwrap());assert_eq!(body.progress.identity,identity);assert_eq!(body.progress.state,ToolRunState::Starting);assert_eq!(body.progress.stage,0);assert_eq!(body.progress.completed,0);assert!(body.progress.total.is_none());assert!(body.progress.counters.is_empty());assert!(body.progress.steps.is_empty());assert!(body.provenance.marks().is_empty());assert!(body.provenance.entities().is_empty());assert!(body.payload.is_none());let heap=drain(output);born+=heap.0;released+=heap.1;}else{assert_eq!(measured(||seed.cancel()).1,(0,0));assert!(seed.take_output(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:usize::MAX,maximum_depth:1,..Default::default()}).unwrap().is_none());}
  let heap=drain(seed);born+=heap.0;released+=heap.1;assert_eq!(original+born,released);
 }}
}
#[test]
fn original_tool_run_progress_metadata_presentation_slot_publishes_only_complete_original_candidates(){
 use super::{ToolRunCapturedView,slot::ToolRunPresentationSlot};
 use semio_framework_tool_run_entities::ToolRunEntityEditGrant;
 use semio_framework_value::{retained_clone::{RetainedCloneGrant,ordered_map::BoundedOrdGrant},retirement::{RetireOwned,controlled::ControlledRetirement}};
 fn step(slot:&mut ToolRunPresentationSlot,bank:&mut semio_framework_value_testing_effect_bank::EffectBank)->(usize,usize){let quote=slot.next_demands(usize::MAX).unwrap();let retirement=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:quote.copy_bytes,maximum_capacity_bytes:quote.capacity_bytes,maximum_release_bytes:quote.release_bytes,maximum_depth:quote.depth};let grant=ToolRunEntityEditGrant{retirement,comparison:BoundedOrdGrant{maximum_items:17,maximum_bytes:4096},maximum_moved_items:17,maximum_moved_bytes:4096,maximum_capacity_bytes:slot.edit_capacity_bound().unwrap()};let o=slot_turn(slot,bank,grant);assert!(o.progress.fits(grant.retirement));o.heap}
 let law:Value=serde_json::from_str(include_str!("../../🗃️slot/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let corpus=fixture(TICKS);
 for stop in std::iter::once(None).chain(law["interruptAfter"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){for order in law["orders"].as_array().unwrap(){let(id,heap)=measured(||law["toolId"].as_str().unwrap().to_owned());let pointer=id.as_ptr();let mut original=heap.0-heap.1;let incoming_identity=identity(&corpus["ticks"][0]["tick"]["identity"]);let(mut slot,heap)=measured(||ToolRunPresentationSlot::new(id,incoming_identity,ToolRunState::Starting));assert_eq!(heap,(0,0));let mut bank=effect_harness::bank();let(mut born,mut released)=(0,0);for _ in 0..10000{if slot.ready(){break;}let heap=step(&mut slot,&mut bank);born+=heap.0;released+=heap.1;}assert!(slot.ready());assert_eq!(slot.body().unwrap().tool_id.get().as_ptr(),pointer);let capture_grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:ToolRunCapturedView::capture_copy_bytes(),maximum_depth:1,..Default::default()};let((capture,receipt),heap)=observed(capture_grant,|effect|slot.capture_view(incoming_identity,ToolRunState::Running,effect).unwrap().unwrap());assert_eq!(heap,(0,0));assert!(receipt.fits(capture_grant));let source_pointer=capture.source_identity();assert_eq!(measured(||capture.borrowed_view()).1,(0,0));let view=capture.borrowed_view();assert_eq!(view.identity,incoming_identity);assert_eq!(view.state,ToolRunState::Running);assert_eq!(view.tool_id.as_ptr(),pointer);assert_eq!(view.progress as *const _,&capture.body().progress as *const _);assert!(view.provisional_entities.is_empty());assert!(view.payload.is_none());assert_eq!(view.progress.state,ToolRunState::Starting);let(tick,heap)=measured(||{let mut input=ToolRunTick{identity:incoming_identity,sequence:1,retract_to:None,append_ops:Vec::new(),append_entities:vec![7,11],steps:Vec::new(),progress:None,trace:Vec::new(),payload_update:Some(ToolRunPayloadUpdate::Replace),payload:Some(vec![1,2,3])};input.progress=Some(progress(&corpus["ticks"][0]["tick"]["progress"]));input});original+=heap.0-heap.1;let incoming_counter=tick.progress.as_ref().unwrap().counters.as_ptr();let incoming_payload=tick.payload.as_ref().unwrap().as_ptr();let quote=ToolRunPresentationSlot::tick_admission_demands();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:quote.copy_bytes,maximum_capacity_bytes:quote.capacity_bytes,maximum_depth:quote.depth,..Default::default()};let(((),receipt),heap)=observed(grant,|effect|slot.begin_tick(tick,1,ToolRunState::Running,0.0,0,effect).unwrap_or_else(|_|panic!("actual original tick admission")));assert_eq!(heap,(receipt.retained_capacity_bytes,0));born+=heap.0;assert!(receipt.fits(grant));let mut turns=0;while !slot.ready()&&turns<stop.unwrap_or(10000){let previous=slot.body().unwrap().progress.sequence;let quote=slot.next_demands(usize::MAX).unwrap();let denied=ToolRunEntityEditGrant{retirement:RetainedCloneGrant{maximum_items:0,..Default::default()},comparison:BoundedOrdGrant{maximum_items:17,maximum_bytes:4096},maximum_moved_items:17,maximum_moved_bytes:4096,maximum_capacity_bytes:slot.edit_capacity_bound().unwrap()};assert_eq!(slot_turn(&mut slot,&mut effect_harness::bank(),denied).heap,(0,0));assert_eq!(slot.next_demands(usize::MAX).unwrap(),quote);assert_eq!(slot.body().unwrap().progress.sequence,previous);let heap=step(&mut slot,&mut bank);born+=heap.0;released+=heap.1;assert_eq!(capture.source_identity(),source_pointer);assert_eq!(capture.body().progress.sequence,0);assert!(capture.body().progress.counters.is_empty());turns+=1;}
  if stop.is_none(){assert!(slot.ready());let body=slot.body().unwrap();assert_eq!(body.progress.sequence,1);assert_eq!(body.progress.counters.as_ptr(),incoming_counter);assert_eq!(body.payload.as_ref().unwrap().get().contiguous().unwrap().as_ptr(),incoming_payload);let entities:Vec<String>=(0..body.provenance.entities().len()).map(|index|body.provenance.entities().get_index(index).unwrap().0.to_string()).collect();assert_eq!(entities,law["expectedEntities"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<Vec<_>>());}
  if stop.is_some(){let before=slot.body().unwrap().progress.sequence;assert_eq!(measured(||slot.cancel_pending()).1,(0,0));for _ in 0..100000{if slot.ready(){break;}let heap=step(&mut slot,&mut bank);born+=heap.0;released+=heap.1;assert_eq!(slot.body().unwrap().progress.sequence,before);}assert!(slot.ready());let(tick,heap)=measured(||ToolRunTick{identity:incoming_identity,sequence:2,retract_to:Some(0),append_ops:Vec::new(),append_entities:vec![law["restartEntity"].as_str().unwrap().parse().unwrap()],steps:Vec::new(),progress:None,trace:Vec::new(),payload_update:None,payload:None});original+=heap.0-heap.1;let quote=ToolRunPresentationSlot::tick_admission_demands();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:quote.copy_bytes,maximum_capacity_bytes:quote.capacity_bytes,maximum_depth:quote.depth,..Default::default()};let (((),receipt),heap)=observed(grant,|effect|slot.begin_tick(tick,2,ToolRunState::Running,0.0,0,effect).unwrap_or_else(|_|panic!("same original slot admits replacement only after pending owners close")));assert_eq!(heap,(receipt.retained_capacity_bytes,0));born+=heap.0;for _ in 0..100000{if slot.ready(){break;}let heap=step(&mut slot,&mut bank);born+=heap.0;released+=heap.1;}assert!(slot.ready());let body=slot.body().unwrap();assert_eq!(body.progress.sequence,2);assert_eq!(body.provenance.entities().len(),1);assert_eq!(*body.provenance.entities().get_index(0).unwrap().0,13);assert_eq!(capture.body().progress.sequence,0);}
  assert_eq!(measured(||slot.cancel()).1,(0,0));let heaps=if order.as_str().unwrap()=="slotFirst"{[effect_harness::retire(&mut bank,slot),drain(capture)]}else{let first=drain(capture);[first,effect_harness::retire(&mut bank,slot)]};for heap in heaps{born+=heap.0;released+=heap.1;}assert_eq!(original+born,released);
 }}
}

fn hex(value:&Value)->Vec<u8>{let text=value.as_str().unwrap();(0..text.len()).step_by(2).map(|index|u8::from_str_radix(&text[index..index+2],16).unwrap()).collect()}
fn identity(value:&Value)->ToolRunIdentity{ToolRunIdentity{id:ToolRunId{app_instance_id:value["id"]["appInstanceId"].as_u64().unwrap()as u32,run:value["id"]["run"].as_u64().unwrap()},generation:value["generation"].as_u64().unwrap()as u32,base_revision:hex(&value["baseRevision"]).try_into().unwrap()}}
fn step(value:&Value)->ToolRunStep{ToolRunStep{sequence:value["sequence"].as_u64().unwrap(),kind:ToolRunStepKind::parse(value["kind"].as_str().unwrap()).unwrap(),stage:value["stage"].as_u64().unwrap()as u16,reason:value["reason"].as_u64().unwrap()as u16,subject:value.get("subject").and_then(Value::as_u64),repeat:value["repeat"].as_u64().unwrap()as u32,args:value["args"].as_array().unwrap().iter().map(|arg|arg.get("unsigned").map_or_else(||ToolRunStepArg::Float(arg["float"].as_f64().unwrap()),|v|ToolRunStepArg::Unsigned(v.as_u64().unwrap()))).collect()}}
fn progress(value:&Value)->ToolRunProgress{ToolRunProgress{identity:identity(&value["identity"]),sequence:value["sequence"].as_u64().unwrap(),state:ToolRunState::parse(value["state"].as_str().unwrap()).unwrap(),stage:value["stage"].as_u64().unwrap()as u16,completed:value["completed"].as_u64().unwrap(),total:value.get("total").and_then(Value::as_u64),counters:value["counters"].as_array().unwrap().iter().map(|counter|ToolRunCounter{counter:counter["counter"].as_u64().unwrap()as u16,value:counter["value"].as_u64().unwrap()}).collect(),units_per_second:value["unitsPerSecond"].as_f64().unwrap()as f32,conflicts:value["conflicts"].as_u64().unwrap()as u32,steps:ToolRunStepRing::from_steps(value["steps"].as_array().unwrap().iter().map(step).collect()).unwrap()}}
fn fixture_payload(bytes:Vec<u8>,identity:ToolRunIdentity)->semio_framework_value_shared_issuance::SealedShared<payload_stream::ToolRunPayloadStream>{
 use payload_stream::update::ToolRunPayloadStreamUpdate;
 let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};
 let mut update=ToolRunPayloadStreamUpdate::empty();let mut input=Some(bytes);let mut previous=None;
 update.admit(&mut previous,&mut input,identity,ToolRunPayloadUpdate::Replace,grant).unwrap().unwrap();
 let mut bank=effect_harness::bank();while !update.complete(){effect_harness::paid(&mut bank,grant,|e,r,recover|if recover{update.recover_advance_into(grant.maximum_copy_bytes,e,r)}else{update.advance_into(grant.maximum_copy_bytes,e,r)});}
 let output=update.take(grant).unwrap().unwrap().0;update.begin_close();while !update.terminal_is_empty(){effect_harness::paid(&mut bank,grant,|e,r,recover|if recover{update.recover_close_into(grant.maximum_copy_bytes,e,r)}else{update.close_into(grant.maximum_copy_bytes,e,r)});}output
}

#[test]
fn original_tool_run_progress_metadata_presentation_update_cancel_after_every_turn_completes_cleanup(){
 use semio_framework_value::{retained_clone::{RetainedCloneGrant,ordered_map::{RetainedOrderedMap,BoundedOrdGrant}},retirement::{RetireOwned,controlled::ControlledRetirement}};
 use semio_framework_value_shared_issuance::{SealedShared,SharedIssuer};
 use super::{ToolRunPresentation,ToolRunPresentationBody,update::ToolRunPresentationUpdate};
 use semio_framework_tool_run_entities::{ToolRunEntityEditGrant,provenance::ToolRunEntityProvenance};
 fn drain<T:RetireOwned>(value:T){effect_harness::retire(&mut effect_harness::bank(),value);}
 let law:Value=serde_json::from_str(include_str!("../../🧬️update/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let corpus=fixture(TICKS);
 for turns in 0..80{
  let marks:RetainedOrderedMap<u128,()>=law["originalMarks"].as_array().unwrap().iter().map(|mark|(((mark["end"].as_u64().unwrap()as u128)<<64)|mark["entity"].as_str().unwrap().parse::<u64>().unwrap()as u128,())).collect();
  let entities=[(7u64,()),(9,())].into_iter().collect();
  let(provenance,_)=run(setup(),|effect|ToolRunEntityProvenance::admit(marks,entities,0,effect)).unwrap_or_else(|_|panic!("cold original provenance"));
  let tool_id=run(setup(),|effect|semio_framework_tool_run_entities::admit_sealed(String::from("draw.command"),effect)).map_err(|(error,_)|error).unwrap().0;
  let progress=progress(&corpus["ticks"][0]["tick"]["progress"]);let tick_identity=progress.identity;let sequence=progress.sequence+1;let quote=ToolRunPresentation::birth_demands().unwrap();
  let(source,_)=run(setup(),|effect|ToolRunPresentation::admit(ToolRunPresentationBody{tool_id,progress,provenance,payload:None},effect)).unwrap_or_else(|_|panic!("cold original presentation"));
  let input=ToolRunTick{payload_update:None,identity:tick_identity,sequence,progress:None,steps:Vec::new(),trace:Vec::new(),append_ops:Vec::new(),append_entities:law["append"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().parse().unwrap()).collect(),retract_to:Some(law["retractTo"].as_u64().unwrap()as u32),payload:None};
  let alias=run(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:ToolRunPresentation::capture_copy_bytes(),maximum_depth:1,..Default::default()},|effect|source.capture(effect)).unwrap().0;let d=ToolRunPresentationUpdate::birth_demands();
  let(mut job,_)=ToolRunPresentationUpdate::admit(alias,input,law["end"].as_u64().unwrap()as u32,ToolRunState::Running,0.0,0,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_depth:d.depth,..Default::default()}).unwrap_or_else(|_|panic!("original presentation state birth was funded"));
  let mut bank=effect_harness::bank();for _ in 0..turns{if job.complete(){break;}let quote=job.next_demands(usize::MAX).unwrap();let grant=ToolRunEntityEditGrant{retirement:RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:quote.copy_bytes,maximum_capacity_bytes:quote.capacity_bytes,maximum_release_bytes:quote.release_bytes,maximum_depth:quote.depth},comparison:BoundedOrdGrant{maximum_items:1,maximum_bytes:32},maximum_moved_items:17,maximum_moved_bytes:17*size_of::<(u128,())>(),maximum_capacity_bytes:job.edit_capacity_bound().unwrap()};turn(&mut job,&mut bank,grant);}
  job.cancel();effect_harness::retire(&mut bank,job);drain(source);
 }
}
